local function UpsertEnchantSource(data, enchants)
    data.sources = data.sources or {}
    for _, source in ipairs(data.sources) do
        if source.label == "Consumables / Enchants / Gems" or source.label == "Enchants / Gems" then
            source.label = "Consumables / Enchants / Gems"
            source.updated = enchants.sourceUpdated or source.updated
            source.url = enchants.sourceURL or source.url
            return
        end
    end
    table.insert(data.sources, { label = "Consumables / Enchants / Gems", updated = enchants.sourceUpdated or "unknown", url = enchants.sourceURL })
end

for specID, enchants in pairs((AGB.GuideEnchantsData and AGB.GuideEnchantsData.specs) or {}) do
    local meta = AGB.SpecIndex and AGB.SpecIndex[specID]
    local data = meta and AGB.Data and AGB.Data[meta.classFile] and AGB.Data[meta.classFile][specID]
    if data and enchants and enchants.sourceURL then
        data.enchants = enchants
        UpsertEnchantSource(data, enchants)
    end
end